import{_ as n,o as e,c as o,a5 as d}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Spec — Subtask theo vai trò & Trình soạn chia phần theo loại task","description":"","frontmatter":{},"headers":[],"relativePath":"feature/subtask-role-workspaces/spec.md","filePath":"feature/subtask-role-workspaces/spec.md"}'),i={name:"feature/subtask-role-workspaces/spec.md"};function h(c,t,a,s,r,l){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="spec-—-subtask-theo-vai-tro-trinh-soan-chia-phan-theo-loai-task" tabindex="-1">Spec — Subtask theo vai trò &amp; Trình soạn chia phần theo loại task <a class="header-anchor" href="#spec-—-subtask-theo-vai-tro-trinh-soan-chia-phan-theo-loai-task" aria-label="Permalink to &quot;Spec — Subtask theo vai trò &amp; Trình soạn chia phần theo loại task&quot;">​</a></h1><p>&gt; <strong>Thay thế</strong> <code>docs/specs/2026-11-09-post-content-media-split-spec.md</code> (chỉ chia Content/Media cho POST). Spec cũ giữ nguyên để tra cứu, không còn hiệu lực. &gt; &gt; Bước ① trong <code>docs/rule/feature-workflow.md</code>. Chưa có plan/task/test, chưa code. &gt; &gt; Lỗi DB <code>media_packages.share_enabled</code> (thiếu migration 2026-11-06) <strong>không thuộc</strong> spec này. &gt; &gt; Mọi trường và quyết định trong spec đã được user chốt ngày 2026-11-10.</p><h2 id="_1-objective" tabindex="-1">1. Objective <a class="header-anchor" href="#_1-objective" aria-label="Permalink to &quot;1. Objective&quot;">​</a></h2><p>Một task lớn trong chiến dịch (bài đăng, sự kiện, thông cáo…) cần nhiều người với vai trò khác nhau. Hiện tại:</p><ul><li><code>TaskDocument.Subtask</code> chỉ có <code>name</code> tự do + assignee/supervisor/hạn/status — không biết subtask đó là việc gì.</li><li>Chỉ assignee của task cha được sửa nội dung (<code>TaskApprovalPolicy.assignee</code>). Người nhận subtask không vào được trình soạn.</li><li>Chỉ POST (trình soạn bài) và SURVEY (form builder) có trình soạn; EVENT_PLAN chỉ có phòng họp, PRESS_RECOMMENDATION chỉ có mô tả.</li></ul><p>Mục tiêu:</p><ol><li>Mỗi loại task có <strong>danh mục subtask chuẩn</strong> (cố định trong code), mỗi vai trò sở hữu một hoặc nhiều <strong>phần (section)</strong> của trình soạn.</li><li>Mỗi loại task có <strong>trình soạn riêng chia phần</strong>; người làm subtask chỉ sửa phần của mình, xem chỉ-đọc phần khác.</li><li><strong>Duyệt từng phần</strong> hai cấp: Manager/supervisor → Client (chỉ phần sản phẩm).</li><li>Thêm 4 loại task mới: <strong>SHORT_VIDEO, KOL_BOOKING, WORKSHOP, EMAIL_NEWSLETTER</strong>.</li><li>EMAIL_NEWSLETTER <strong>gửi thật</strong> qua hạ tầng mail sẵn có, quota theo gói.</li></ol><p>Làm trong <strong>một đợt</strong> cho cả 8 loại (LIVESTREAM vẫn bị loại khỏi scope theo AGENTS.md).</p><h2 id="_2-thuat-ngu" tabindex="-1">2. Thuật ngữ <a class="header-anchor" href="#_2-thuat-ngu" aria-label="Permalink to &quot;2. Thuật ngữ&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Thuật ngữ</th><th>Nghĩa</th></tr></thead><tbody><tr><td>Role hệ thống</td><td>6 tên cố định: Guest, Owner, Manager, Creator, Client, Admin. <strong>Không thay đổi.</strong></td></tr><tr><td>Vai trò công việc (<code>subtaskRole</code>)</td><td>Loại việc của một subtask (vd <code>POST_CONTENT</code>). Không phải role hệ thống; quyền sửa phần xét theo subtask được giao.</td></tr><tr><td>Phần (section)</td><td>Một vùng nội dung trong trình soạn, có key <code>TYPE.SECTION</code> (vd <code>POST.CAPTION</code>), có vòng đời duyệt riêng.</td></tr><tr><td>Phần sản phẩm (output)</td><td>Phần Client nhìn thấy và duyệt.</td></tr><tr><td>Phần nội bộ (internal)</td><td>Phần chỉ agency thấy; Client không thấy, không duyệt.</td></tr><tr><td>Chủ phần</td><td>Assignee của subtask có <code>subtaskRole</code> sở hữu phần đó.</td></tr><tr><td>Điều phối</td><td>Assignee của task cha (<code>TaskDocument.assigneeId</code>).</td></tr><tr><td>Supervisor</td><td><code>Subtask.supervisorOverrideId</code>, mặc định là assignee task cha (logic <code>CampaignSubtaskService.supervisor</code>).</td></tr></tbody></table><h2 id="_3-danh-muc-subtask-chuan-phan-soan" tabindex="-1">3. Danh mục subtask chuẩn &amp; phần soạn <a class="header-anchor" href="#_3-danh-muc-subtask-chuan-phan-soan" aria-label="Permalink to &quot;3. Danh mục subtask chuẩn &amp; phần soạn&quot;">​</a></h2><p>Cột &quot;Hiển thị&quot;: <strong>O</strong> = output (Client thấy &amp; duyệt), <strong>I</strong> = internal.</p><h3 id="_3-1-post-—-bai-đang-mang-xa-hoi-5-vai-tro-trinh-soan-hien-co-editor" tabindex="-1">3.1 POST — Bài đăng mạng xã hội (5 vai trò, trình soạn hiện có <code>/editor</code>) <a class="header-anchor" href="#_3-1-post-—-bai-đang-mang-xa-hoi-5-vai-tro-trinh-soan-hien-co-editor" aria-label="Permalink to &quot;3.1 POST — Bài đăng mạng xã hội (5 vai trò, trình soạn hiện có `/editor`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>subtaskRole</th><th>Tên vai trò</th><th>Phần sở hữu</th><th>Trường</th><th>Hiển thị</th></tr></thead><tbody><tr><td><code>POST_RESEARCH</code></td><td>Nghiên cứu / Phỏng vấn</td><td><code>POST.BRIEF</code> (mới)</td><td>ghi chú phỏng vấn (rich text), trích dẫn nguồn (list text+link), file tư liệu (tham chiếu Material, gồm ghi âm)</td><td>I</td></tr><tr><td><code>POST_CONTENT</code></td><td>Viết content</td><td><code>POST.CAPTION</code></td><td>caption, hashtag, CTA (= <code>SavePostRequest.caption/hashtags</code>)</td><td>O</td></tr><tr><td><code>POST_MEDIA</code></td><td>Media (quay/chụp/thiết kế)</td><td><code>POST.MEDIA</code></td><td>media list (<code>PostMedia</code>), watermark (luồng watermark đã có trong <code>MediaDropzone</code>)</td><td>O</td></tr><tr><td><code>POST_EDITING</code></td><td>Biên tập</td><td><code>POST.CAPTION</code> (chung với Content)</td><td>sửa caption/hashtag</td><td>O</td></tr><tr><td><code>POST_PUBLISHING</code></td><td>Đăng bài</td><td><code>POST.CHANNELS</code></td><td>targetPlatforms (Facebook/Instagram/TikTok/Threads), scheduledAt, nút publish</td><td>O</td></tr></tbody></table><p><strong>Luật chồng phần:</strong> <code>POST_EDITING</code> chỉ sửa <code>POST.CAPTION</code> khi phần đã ở trạng thái <code>SUBMITTED</code> trở lên (Content đã nộp); khi Editing sửa, Content mất quyền sửa cho tới khi phần bị RETURNED. <code>POST_PUBLISHING</code> sửa kênh/lịch bất cứ lúc nào phần còn mở, nhưng <strong>publish/schedule thật</strong> chỉ sau khi task cha được duyệt xong (luồng publish hiện có).</p><h3 id="_3-2-short-video-—-video-ngan-moi-dung-lai-trinh-soan-post-phan-kich-ban" tabindex="-1">3.2 SHORT_VIDEO — Video ngắn (mới; dùng lại trình soạn POST + phần Kịch bản) <a class="header-anchor" href="#_3-2-short-video-—-video-ngan-moi-dung-lai-trinh-soan-post-phan-kich-ban" aria-label="Permalink to &quot;3.2 SHORT_VIDEO — Video ngắn (mới; dùng lại trình soạn POST + phần Kịch bản)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>subtaskRole</th><th>Tên</th><th>Phần</th><th>Trường</th><th>Hiển thị</th></tr></thead><tbody><tr><td><code>VIDEO_SCRIPT</code></td><td>Ý tưởng &amp; Kịch bản</td><td><code>VIDEO.SCRIPT</code> (mới)</td><td>ý tưởng (text), kịch bản theo cảnh (list: cảnh, lời thoại, ghi chú hình ảnh, thời lượng)</td><td>O</td></tr><tr><td><code>VIDEO_SHOOT</code></td><td>Quay</td><td><code>VIDEO.SHOOT</code></td><td><strong>chừa slot cho code của Ân</strong> — spec này chỉ đặt key + quyền, không định nghĩa UI</td><td>I</td></tr><tr><td><code>VIDEO_EDIT</code></td><td>Dựng / hậu kỳ</td><td><code>VIDEO.EDIT</code></td><td><strong>chừa slot cho code của Ân</strong></td><td>O</td></tr><tr><td><code>VIDEO_PUBLISH</code></td><td>Caption &amp; Đăng</td><td><code>VIDEO.CAPTION</code>, <code>VIDEO.CHANNELS</code></td><td>như <code>POST.CAPTION</code> + <code>POST.CHANNELS</code>; kênh giới hạn TikTok, Instagram (Reels), Facebook (Reels)</td><td>O</td></tr></tbody></table><h3 id="_3-3-survey-—-khao-sat-trinh-soan-hien-co-form-builder-surveyoverviewcard" tabindex="-1">3.3 SURVEY — Khảo sát (trình soạn hiện có: form builder <code>SurveyOverviewCard</code>) <a class="header-anchor" href="#_3-3-survey-—-khao-sat-trinh-soan-hien-co-form-builder-surveyoverviewcard" aria-label="Permalink to &quot;3.3 SURVEY — Khảo sát (trình soạn hiện có: form builder `SurveyOverviewCard`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>subtaskRole</th><th>Tên</th><th>Phần</th><th>Trường</th><th>Hiển thị</th></tr></thead><tbody><tr><td><code>SURVEY_DESIGN</code></td><td>Thiết kế bảng hỏi</td><td><code>SURVEY.FORM</code></td><td>câu hỏi (dữ liệu <code>POST /survey</code> hiện có)</td><td>O</td></tr><tr><td><code>SURVEY_DISTRIBUTE</code></td><td>Phân phối &amp; thu thập</td><td><code>SURVEY.DISTRIBUTION</code></td><td>link public (token <code>/public/surveys/{token}</code> có sẵn), kênh phát (text), hạn đóng, chỉ tiêu số phản hồi</td><td>O</td></tr><tr><td><code>SURVEY_ANALYSIS</code></td><td>Phân tích &amp; báo cáo</td><td><code>SURVEY.REPORT</code></td><td>insight, kết luận, đề xuất (rich text) + số liệu từ <code>/survey/analysis</code></td><td>O</td></tr></tbody></table><h3 id="_3-4-event-plan-—-ke-hoach-su-kien-trinh-soan-moi" tabindex="-1">3.4 EVENT_PLAN — Kế hoạch sự kiện (trình soạn mới) <a class="header-anchor" href="#_3-4-event-plan-—-ke-hoach-su-kien-trinh-soan-moi" aria-label="Permalink to &quot;3.4 EVENT_PLAN — Kế hoạch sự kiện (trình soạn mới)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>subtaskRole</th><th>Tên</th><th>Phần</th><th>Trường</th><th>Hiển thị</th></tr></thead><tbody><tr><td><code>EVENT_AGENDA</code></td><td>Concept &amp; Agenda</td><td><code>EVENT.AGENDA</code></td><td>concept, mục tiêu, thời gian/địa điểm dự kiến, agenda (list: giờ, hạng mục, phụ trách)</td><td>O</td></tr><tr><td><code>EVENT_LOGISTICS</code></td><td>Hậu cần &amp; Địa điểm</td><td><code>EVENT.LOGISTICS</code></td><td>venue, vendor (list: tên, hạng mục, chi phí VND, liên hệ), ngân sách tổng, checklist vật tư</td><td>I</td></tr><tr><td><code>EVENT_PROMOTION</code></td><td>Truyền thông sự kiện</td><td><code>EVENT.PROMOTION</code></td><td>kế hoạch truyền thông (rich text), danh sách khách mời (list: tên, đơn vị, trạng thái mời)</td><td>O</td></tr><tr><td><code>EVENT_ONSITE</code></td><td>Điều phối tại chỗ</td><td><code>EVENT.RUNSHEET</code></td><td>run-sheet (list: giờ, việc, người phụ trách), phân công nhân sự</td><td>I</td></tr><tr><td><code>EVENT_REPORT</code></td><td>Báo cáo sau sự kiện</td><td><code>EVENT.REPORT</code></td><td>kết quả, số khách tham dự, ảnh (Material), bài học</td><td>O</td></tr></tbody></table><h3 id="_3-5-press-recommendation-—-bao-chi-trinh-soan-moi-chi-ghi-nhan" tabindex="-1">3.5 PRESS_RECOMMENDATION — Báo chí (trình soạn mới, <strong>chỉ ghi nhận</strong>) <a class="header-anchor" href="#_3-5-press-recommendation-—-bao-chi-trinh-soan-moi-chi-ghi-nhan" aria-label="Permalink to &quot;3.5 PRESS_RECOMMENDATION — Báo chí (trình soạn mới, **chỉ ghi nhận**)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>subtaskRole</th><th>Tên</th><th>Phần</th><th>Trường</th><th>Hiển thị</th></tr></thead><tbody><tr><td><code>PRESS_MEDIA_LIST</code></td><td>Lập danh sách báo</td><td><code>PRESS.MEDIA_LIST</code></td><td>list: tên báo, chuyên mục, nhà báo, email/điện thoại, ghi chú</td><td>I</td></tr><tr><td><code>PRESS_RELEASE</code></td><td>Viết thông cáo</td><td><code>PRESS.RELEASE</code></td><td>tiêu đề, sapo, nội dung (rich text), file đính kèm (Material)</td><td>O</td></tr><tr><td><code>PRESS_PITCHING</code></td><td>Liên hệ &amp; pitching</td><td><code>PRESS.CONTACT_LOG</code></td><td>nhật ký (list: ngày, báo, người liên hệ, kênh, kết quả). <strong>Hệ thống không gửi mail cho nhà báo.</strong></td><td>I</td></tr><tr><td><code>PRESS_TRACKING</code></td><td>Theo dõi đưa tin</td><td><code>PRESS.COVERAGE</code></td><td>list: báo, link bài, ngày đăng, ảnh chụp bài (Material)</td><td>O</td></tr></tbody></table><h3 id="_3-6-kol-booking-—-kol-influencer-moi-chi-ghi-nhan-kol-khong-co-tai-khoan" tabindex="-1">3.6 KOL_BOOKING — KOL/Influencer (mới, <strong>chỉ ghi nhận</strong>, KOL không có tài khoản) <a class="header-anchor" href="#_3-6-kol-booking-—-kol-influencer-moi-chi-ghi-nhan-kol-khong-co-tai-khoan" aria-label="Permalink to &quot;3.6 KOL_BOOKING — KOL/Influencer (mới, **chỉ ghi nhận**, KOL không có tài khoản)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>subtaskRole</th><th>Tên</th><th>Phần</th><th>Trường</th><th>Hiển thị</th></tr></thead><tbody><tr><td><code>KOL_SOURCING</code></td><td>Tìm &amp; đề xuất KOL</td><td><code>KOL.SHORTLIST</code></td><td>list: tên, kênh (4 nền tảng), link, follower, tỉ lệ tương tác, lý do chọn</td><td>O</td></tr><tr><td><code>KOL_NEGOTIATION</code></td><td>Đàm phán</td><td><code>KOL.DEAL</code></td><td>KOL đã chọn, giá thỏa thuận (VND), hạng mục deliverable, điều khoản (text). <strong>Không thanh toán.</strong></td><td>I</td></tr><tr><td><code>KOL_BRIEF</code></td><td>Brief cho KOL</td><td><code>KOL.BRIEF</code></td><td>key message, do/don&#39;t, hashtag bắt buộc, deadline đăng</td><td>O</td></tr><tr><td><code>KOL_CONTENT_REVIEW</code></td><td>Duyệt nội dung KOL</td><td><code>KOL.DRAFT</code></td><td>bản nháp KOL gửi (agency tải lên: caption + media Material), ghi chú duyệt</td><td>O</td></tr><tr><td><code>KOL_TRACKING</code></td><td>Theo dõi &amp; báo cáo</td><td><code>KOL.REPORT</code></td><td>link bài KOL, ngày đăng, view/like/comment/share nhập tay</td><td>O</td></tr></tbody></table><h3 id="_3-7-workshop-moi-khop-packageservicetype-workshop-support" tabindex="-1">3.7 WORKSHOP (mới; khớp <code>PackageServiceType.WORKSHOP_SUPPORT</code>) <a class="header-anchor" href="#_3-7-workshop-moi-khop-packageservicetype-workshop-support" aria-label="Permalink to &quot;3.7 WORKSHOP (mới; khớp `PackageServiceType.WORKSHOP_SUPPORT`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>subtaskRole</th><th>Tên</th><th>Phần</th><th>Trường</th><th>Hiển thị</th></tr></thead><tbody><tr><td><code>WORKSHOP_PROGRAM</code></td><td>Nội dung chương trình</td><td><code>WORKSHOP.PROGRAM</code></td><td>chủ đề, agenda (list), slide/tài liệu (Material)</td><td>O</td></tr><tr><td><code>WORKSHOP_SPEAKER</code></td><td>Diễn giả</td><td><code>WORKSHOP.SPEAKERS</code></td><td>list: tên, chức danh, chủ đề, trạng thái mời (INVITED/CONFIRMED/DECLINED)</td><td>O</td></tr><tr><td><code>WORKSHOP_LOGISTICS</code></td><td>Hậu cần</td><td><code>WORKSHOP.LOGISTICS</code></td><td>hình thức (offline/online), địa điểm hoặc phòng online (dùng lại phòng họp <code>meetingUrl</code> hiện có), chi phí</td><td>I</td></tr><tr><td><code>WORKSHOP_REGISTRATION</code></td><td>Đăng ký &amp; truyền thông</td><td><code>WORKSHOP.REGISTRATION</code></td><td>form đăng ký — <strong>dùng lại form builder SURVEY</strong> + link public; kế hoạch truyền thông</td><td>O</td></tr><tr><td><code>WORKSHOP_REPORT</code></td><td>Tổng kết</td><td><code>WORKSHOP.REPORT</code></td><td>số đăng ký/tham dự, feedback, ảnh, bài học</td><td>O</td></tr></tbody></table><h3 id="_3-8-email-newsletter-moi-gui-that" tabindex="-1">3.8 EMAIL_NEWSLETTER (mới, <strong>gửi thật</strong>) <a class="header-anchor" href="#_3-8-email-newsletter-moi-gui-that" aria-label="Permalink to &quot;3.8 EMAIL_NEWSLETTER (mới, **gửi thật**)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>subtaskRole</th><th>Tên</th><th>Phần</th><th>Trường</th><th>Hiển thị</th></tr></thead><tbody><tr><td><code>EMAIL_CONTENT</code></td><td>Viết nội dung</td><td><code>EMAIL.CONTENT</code></td><td>subject, preheader, nội dung khối (dùng <code>BlockBuilder</code> / <code>MailBlockType</code> của mail-templates)</td><td>O</td></tr><tr><td><code>EMAIL_DESIGN</code></td><td>Thiết kế template</td><td><code>EMAIL.DESIGN</code></td><td>layout, màu/logo thương hiệu Client (block builder)</td><td>O</td></tr><tr><td><code>EMAIL_SEND</code></td><td>Danh sách &amp; lịch gửi</td><td><code>EMAIL.AUDIENCE</code></td><td>nhóm người nhận (recipient group của Client), lịch gửi, nút gửi/test</td><td>O (Client xác nhận gửi cho ai, khi nào)</td></tr><tr><td><code>EMAIL_REPORT</code></td><td>Báo cáo</td><td><code>EMAIL.REPORT</code></td><td>số đã gửi/thành công/lỗi-bounce/huỷ đăng ký từ mail batch; ô nhận xét. Không có open/click (§16.3)</td><td>O</td></tr></tbody></table><h2 id="_4-ma-tran-quyen" tabindex="-1">4. Ma trận quyền <a class="header-anchor" href="#_4-ma-tran-quyen" aria-label="Permalink to &quot;4. Ma trận quyền&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Đối tượng</th><th>Sửa phần của mình</th><th>Sửa phần khác</th><th>Xem phần internal</th><th>Duyệt/trả phần</th><th>Nộp task cha</th></tr></thead><tbody><tr><td>Điều phối (assignee task cha; Creator hoặc Manager)</td><td>✔</td><td>✔ (mọi phần)</td><td>✔</td><td>✖</td><td>✔ (khi mọi phần đủ điều kiện)</td></tr><tr><td>Chủ phần (assignee subtask có <code>subtaskRole</code>)</td><td>✔ khi phần ở <code>DRAFT</code>/<code>RETURNED</code></td><td>✖ (chỉ đọc)</td><td>✔</td><td>✖</td><td>✖</td></tr><tr><td>Manager của workspace</td><td>✔ (mọi phần)</td><td>✔</td><td>✔</td><td>✔ cấp nội bộ</td><td>như hiện tại</td></tr><tr><td>Supervisor của subtask</td><td>theo vai trò khác của họ</td><td>—</td><td>✔</td><td>✔ cấp nội bộ cho phần của subtask đó</td><td>—</td></tr><tr><td>Client</td><td>✖</td><td>✖</td><td>✖ (ẩn hoàn toàn)</td><td>✔ cấp Client, chỉ phần <strong>O</strong>, chỉ sau khi Manager duyệt</td><td>✖</td></tr><tr><td>Assignee subtask tự do (không <code>subtaskRole</code>)</td><td>✖</td><td>✖ (chỉ đọc)</td><td>✔</td><td>✖</td><td>✖</td></tr><tr><td>Subtask cũ (tạo trước tính năng, <code>subtaskRole = null</code>)</td><td>xử lý như subtask tự do</td><td></td><td></td><td></td><td></td></tr><tr><td>Owner, Admin</td><td>giữ nguyên quyền hiện có, không thêm</td><td></td><td></td><td></td><td></td></tr></tbody></table><ul><li>Một người nhận nhiều subtask có vai trò trong cùng task → quyền là <strong>hợp</strong> các phần.</li><li>Một vai trò có thể được giao cho nhiều subtask (vd 2 người <code>POST_CONTENT</code>) → cùng sửa phần đó, xung đột xử lý bằng revision (§5.4).</li><li>Phần không có chủ (Manager bỏ vai trò đó khỏi danh mục khi tạo) → chỉ Điều phối/Manager sửa; không cần duyệt nội bộ riêng, duyệt cùng lúc khi nộp task cha.</li></ul><h2 id="_5-vong-đoi-phan-luat-khoa" tabindex="-1">5. Vòng đời phần &amp; luật khoá <a class="header-anchor" href="#_5-vong-đoi-phan-luat-khoa" aria-label="Permalink to &quot;5. Vòng đời phần &amp; luật khoá&quot;">​</a></h2><h3 id="_5-1-trang-thai-phan" tabindex="-1">5.1 Trạng thái phần <a class="header-anchor" href="#_5-1-trang-thai-phan" aria-label="Permalink to &quot;5.1 Trạng thái phần&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DRAFT ──submit──▶ SUBMITTED ──Manager/supervisor approve──▶ INTERNAL_APPROVED</span></span>\n<span class="line"><span>  ▲                   │                                            │</span></span>\n<span class="line"><span>  │◀──return (ghi chú)┘                                            │ (phần O)</span></span>\n<span class="line"><span>  │                                                                ▼</span></span>\n<span class="line"><span>RETURNED ◀──────── Client return (ghi chú) ─────────────── CLIENT_APPROVED</span></span></code></pre></div><ul><li>Phần <strong>I</strong> dừng ở <code>INTERNAL_APPROVED</code> (trạng thái cuối).</li><li>Phần <strong>O</strong> cần thêm <code>CLIENT_APPROVED</code> nếu task có <code>requiresClientApproval = true</code>; nếu <code>false</code> thì <code>INTERNAL_APPROVED</code> là cuối.</li><li><code>RETURNED</code> = như <code>DRAFT</code>, kèm ghi chú của người trả. Client trả → mở khoá cho chủ phần, sửa xong đi lại <code>SUBMITTED → INTERNAL_APPROVED → CLIENT_APPROVED</code>. Các phần Client đã duyệt giữ nguyên.</li><li>Manager có thể <strong>mở lại</strong> phần đã duyệt (về <code>RETURNED</code>) khi task cha chưa nộp.</li></ul><h3 id="_5-2-khoa" tabindex="-1">5.2 Khoá <a class="header-anchor" href="#_5-2-khoa" aria-label="Permalink to &quot;5.2 Khoá&quot;">​</a></h3><ul><li>Chủ phần chỉ sửa khi phần ở <code>DRAFT</code>/<code>RETURNED</code>. Từ <code>SUBMITTED</code> trở đi khoá với chủ phần.</li><li>Điều phối và Manager sửa được ở mọi trạng thái trước khi task cha nộp; sửa một phần đã <code>INTERNAL_APPROVED</code>/<code>CLIENT_APPROVED</code> đưa phần đó về <code>SUBMITTED</code> (cần duyệt lại). Phần O đã <code>CLIENT_APPROVED</code> mà bị sửa thì Client phải duyệt lại, để không đăng/gửi nội dung Client chưa thấy.</li><li>Luật chồng phần <code>POST.CAPTION</code> / <code>VIDEO.CAPTION</code>: §3.1.</li></ul><h3 id="_5-3-lien-ket-voi-subtask-va-task-cha" tabindex="-1">5.3 Liên kết với subtask và task cha <a class="header-anchor" href="#_5-3-lien-ket-voi-subtask-va-task-cha" aria-label="Permalink to &quot;5.3 Liên kết với subtask và task cha&quot;">​</a></h3><ul><li>Subtask có <code>subtaskRole</code> chuyển <code>FINISHED</code> <strong>tự động</strong> khi mọi phần nó sở hữu đạt trạng thái cuối; chủ subtask không tự đánh dấu FINISHED được.</li><li>Nộp task cha (<code>POST /tasks/{taskId}/submit</code>, <code>TaskApprovalService</code>) giữ luật hiện tại <code>TASK_SUBTASKS_UNFINISHED</code>, thêm luật: mọi phần đã <code>INTERNAL_APPROVED</code> trở lên. Với Client per-section, sau khi mọi phần O đã <code>CLIENT_APPROVED</code> thì task cha tự sang trạng thái đã duyệt; bước duyệt Client cấp task (<code>reviewStep = CLIENT</code>) được thay bằng duyệt từng phần.</li><li>Chỉ subtask đến từ danh mục mới có <code>subtaskRole</code>; Manager vẫn thêm được subtask tự do.</li></ul><h3 id="_5-4-chay-song-song-đong-thoi" tabindex="-1">5.4 Chạy song song &amp; đồng thời <a class="header-anchor" href="#_5-4-chay-song-song-đong-thoi" aria-label="Permalink to &quot;5.4 Chạy song song &amp; đồng thời&quot;">​</a></h3><ul><li>Mọi subtask làm song song; không có thứ tự bắt buộc ngoài luật chồng phần.</li><li>Không sửa cùng một phần đồng thời: mỗi lần lưu gửi <code>expectedRevision</code>; lệch → <code>TASK_REVISION_CONFLICT</code> (đã có, dùng <code>workflowRevision</code>). Revision <strong>theo từng phần</strong> để hai người sửa hai phần khác nhau không chặn nhau (quyết định kỹ thuật).</li></ul><h2 id="_6-user-stories" tabindex="-1">6. User Stories <a class="header-anchor" href="#_6-user-stories" aria-label="Permalink to &quot;6. User Stories&quot;">​</a></h2><ol><li>Là <strong>Manager</strong>, khi tạo subtask cho một task POST, tôi thấy sẵn 5 vai trò chuẩn, bỏ bớt vai trò không cần, gán người và hạn cho từng vai trò, và vẫn thêm được subtask tự do.</li><li>Là <strong>Creator</strong> được giao subtask &quot;Viết content&quot;, tôi mở trình soạn của task, chỉ sửa được caption/hashtag; media, kênh, brief hiển thị chỉ-đọc.</li><li>Là <strong>Creator</strong> làm &quot;Biên tập&quot;, tôi chỉ sửa được caption sau khi người viết đã nộp phần.</li><li>Là <strong>Manager/supervisor</strong>, tôi duyệt hoặc trả lại từng phần kèm ghi chú, trên web hoặc mobile.</li><li>Là <strong>Client</strong>, tôi chỉ thấy các phần sản phẩm đã được Manager duyệt, duyệt hoặc trả lại từng phần; tôi không thấy brief, giá KOL, ngân sách, nhật ký liên hệ báo chí.</li><li>Là <strong>Creator</strong> điều phối (assignee task cha), tôi sửa được mọi phần và nộp task khi mọi phần đủ điều kiện.</li><li>Là <strong>Creator</strong> làm &quot;Danh sách &amp; lịch gửi&quot; của EMAIL_NEWSLETTER, tôi chọn nhóm người nhận đã có đồng ý nhận mail và gửi/lên lịch sau khi Client duyệt nội dung, trong giới hạn quota gói.</li><li>Là <strong>Manager</strong>, tôi import CSV danh sách liên hệ của Client, bắt buộc cột xác nhận đồng ý; dòng không đồng ý bị loại.</li><li>Là <strong>Creator</strong> làm KOL/Press, tôi ghi nhận shortlist, giá, nhật ký liên hệ, link bài — hệ thống không gửi mail, không thanh toán.</li><li>Là <strong>Manager</strong> dùng mobile, tôi xem subtask được giao, xem nội dung từng phần, duyệt/trả phần.</li></ol><h2 id="_7-acceptance-criteria" tabindex="-1">7. Acceptance Criteria <a class="header-anchor" href="#_7-acceptance-criteria" aria-label="Permalink to &quot;7. Acceptance Criteria&quot;">​</a></h2><p><strong>Danh mục &amp; subtask</strong></p><ul><li>AC1: <code>GET</code> danh mục theo <code>TaskType</code> trả đúng các vai trò ở §3, cố định trong code (không có UI cấu hình).</li><li>AC2: Tạo subtask từ danh mục lưu <code>subtaskRole</code>; tạo subtask tự do lưu <code>subtaskRole = null</code>. Subtask cũ đọc ra <code>subtaskRole = null</code>, không lỗi.</li><li>AC3: Một <code>subtaskRole</code> hợp lệ chỉ khi thuộc đúng <code>TaskType</code> của task cha; sai → <code>VALIDATION_ERROR</code>.</li></ul><p><strong>Quyền sửa</strong> (kiểm ở backend, frontend chỉ phản ánh)</p><ul><li>AC4: Chủ phần sửa phần mình khi <code>DRAFT</code>/<code>RETURNED</code>; sửa phần khác → <code>FORBIDDEN</code>.</li><li>AC5: Assignee subtask tự do không sửa được phần nào.</li><li>AC6: Điều phối và Manager sửa mọi phần trước khi task cha nộp.</li><li>AC7: <code>POST_EDITING</code> sửa <code>POST.CAPTION</code> khi phần đang <code>DRAFT</code> (Content chưa nộp) → <code>FORBIDDEN</code>.</li><li>AC8: Endpoint lưu bài hiện có <code>POST /tasks/{taskId}/post</code> áp quyền theo phần: chỉ chấp nhận thay đổi trường thuộc phần người gọi được sửa; trường khác thay đổi → <code>FORBIDDEN</code> (không lặng lẽ bỏ qua).</li></ul><p><strong>Duyệt</strong></p><ul><li>AC9: Chỉ Manager hoặc supervisor của subtask duyệt/trả phần ở cấp nội bộ.</li><li>AC10: Client chỉ thấy phần O ở trạng thái <code>INTERNAL_APPROVED</code> trở lên; phần I không có trong response cho Client (lọc ở backend).</li><li>AC11: Client trả phần → phần về <code>RETURNED</code> kèm ghi chú, chủ phần nhận thông báo; các phần đã <code>CLIENT_APPROVED</code> không đổi.</li><li>AC12: Nộp task cha bị chặn nếu còn phần chưa <code>INTERNAL_APPROVED</code>.</li></ul><p><strong>Email</strong></p><ul><li>AC13: Import CSV cần cột <code>email</code>, <code>name</code>, <code>consent</code>; dòng <code>consent</code> khác <code>true/yes/1</code> bị loại và báo số dòng loại; email nằm trong suppression list bị loại.</li><li>AC14: Gửi chỉ khi <code>EMAIL.CONTENT</code> và <code>EMAIL.DESIGN</code> đã <code>CLIENT_APPROVED</code> (hoặc <code>INTERNAL_APPROVED</code> nếu task không cần Client duyệt), và người gọi là chủ <code>EMAIL_SEND</code> (hoặc điều phối/Manager).</li><li>AC15: Quota tháng theo gói: BASIC 1.000, PRO 10.000, ENTERPRISE 50.000 email/tháng/agency; vượt → chặn gửi, báo số còn lại. Newsletter dùng bộ đếm riêng + giới hạn tốc độ gửi/ngày cấu hình được; giới hạn ngày của mail hệ thống (<code>MailQuotaService</code>, <code>mail.quota.*</code>) không bị Newsletter tiêu tốn (§16.1).</li><li>AC16: Mỗi mail có link unsubscribe (dùng <code>/public/mail/unsubscribe</code> có sẵn); người hủy vào suppression của workspace.</li><li>AC17: Mail gửi từ domain BrandHub, tên người gửi hiển thị = tên thương hiệu Client.</li></ul><p><strong>Mobile</strong></p><ul><li>AC18: Mobile hiển thị subtask được giao, nội dung từng phần chỉ-đọc, nút duyệt/trả cho Manager/supervisor/Client theo đúng quyền. Không có trình soạn trên mobile.</li></ul><p><strong>i18n (bắt buộc)</strong></p><ul><li>AC19: Mọi text mới dùng key, thêm đồng thời <code>vi</code> + <code>en</code> (key-parallel), không hardcode: <ul><li><code>tasks.subtaskRoles.&lt;ROLE&gt;</code> — tên vai trò (VD <code>tasks.subtaskRoles.POST_CONTENT</code>)</li><li><code>tasks.sections.&lt;TYPE&gt;.&lt;SECTION&gt;.title|fields.*</code> — tiêu đề &amp; nhãn trường từng phần</li><li><code>tasks.sectionStatus.&lt;STATUS&gt;</code> — DRAFT/SUBMITTED/INTERNAL_APPROVED/CLIENT_APPROVED/RETURNED</li><li><code>tasks.sectionActions.*</code> — submit/approve/return/reopen, thông báo khoá, lỗi quyền</li><li><code>tasks.types.&lt;TYPE&gt;</code> — 4 loại mới</li><li><code>campaign.timeline.catalog.*</code> — gợi ý danh mục khi tạo subtask</li><li><code>editor.sections.*</code> — banner chỉ-đọc, tên chủ phần</li><li><code>mailTemplate.contactImport.*</code>, <code>mailTemplate.quota.monthly*</code> — import CSV &amp; quota tháng</li><li>mobile: cùng namespace trong locale của <code>brandhub-mobile-app</code></li></ul></li></ul><p><strong>Light/Dark (bắt buộc)</strong></p><ul><li>AC20: Badge trạng thái phần, viền phần bị khoá, banner chỉ-đọc dùng token theme/<code>dark:</code> variant sẵn có (<code>bg-muted</code>, <code>text-muted-foreground</code>, <code>brand-orange</code>, màu trạng thái như <code>TaskStatusControl</code>), không hex cứng. Kiểm tra cả hai theme.</li></ul><h2 id="_8-ui-ux" tabindex="-1">8. UI/UX <a class="header-anchor" href="#_8-ui-ux" aria-label="Permalink to &quot;8. UI/UX&quot;">​</a></h2><ul><li><strong>Tạo subtask (timeline &amp; task detail):</strong> <code>TimelineSubtaskCreator</code> / <code>CampaignSubtasks</code> thêm bước &quot;Gợi ý theo danh mục&quot;: danh sách vai trò của loại task, mỗi dòng tick/bỏ, chọn assignee, hạn; nút &quot;Thêm subtask tự do&quot; giữ như cũ. Subtask có vai trò hiện badge tên vai trò.</li><li><strong>Trình soạn chia phần:</strong> mỗi phần là một khối có tiêu đề, tên chủ phần, badge trạng thái, nút theo quyền (Nộp / Duyệt / Trả lại / Mở lại). Phần không được sửa: nội dung hiển thị bình thường nhưng input disabled + biểu tượng khoá + tooltip &quot;Phần của {tên}&quot;. <ul><li>POST &amp; SHORT_VIDEO: mở rộng <code>/workspaces/:id/tasks/:taskId/editor</code> (<code>pages/editor</code>), thêm khối Brief (POST) / Kịch bản (VIDEO), khối Shoot/Edit của VIDEO là slot rỗng cho code của Ân.</li><li>SURVEY: gắn khung phần quanh form builder hiện có (<code>SurveyOverviewCard</code>), thêm khối Phân phối, Báo cáo.</li><li>EVENT_PLAN, PRESS_RECOMMENDATION, KOL_BOOKING, WORKSHOP, EMAIL_NEWSLETTER: trình soạn mới cùng một bộ khung phần (layout dùng chung, nội dung khối theo loại). EMAIL dùng lại <code>BlockBuilder</code>, <code>MailPreview</code>, <code>RecipientPicker</code>.</li></ul></li><li><strong>Task detail (<code>TaskWorkflowContent</code>):</strong> nút mở trình soạn hiển thị cho mọi loại (hiện chỉ POST/SURVEY), kèm tóm tắt tiến độ phần (vd 3/5 phần đã duyệt).</li><li><strong>Client portal:</strong> danh sách phần chờ duyệt theo task; mỗi phần xem + Duyệt / Trả lại (bắt buộc ghi chú khi trả).</li><li><strong>Mobile:</strong> màn task detail thêm tab &quot;Phần&quot;, chỉ đọc + nút duyệt/trả.</li></ul><h2 id="_9-api-contract" tabindex="-1">9. API Contract <a class="header-anchor" href="#_9-api-contract" aria-label="Permalink to &quot;9. API Contract&quot;">​</a></h2><p>Mở rộng endpoint hiện có, không nhân bản. Mọi response bọc <code>ApiResponse</code>. Path gốc <code>/api/v1/workspaces/{workspaceId}</code>.</p><h3 id="_9-1-mo-rong-hien-co" tabindex="-1">9.1 Mở rộng hiện có <a class="header-anchor" href="#_9-1-mo-rong-hien-co" aria-label="Permalink to &quot;9.1 Mở rộng hiện có&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Endpoint (hiện có)</th><th>Thay đổi</th></tr></thead><tbody><tr><td><code>GET/POST/PATCH /tasks/{taskId}/subtasks…</code> (<code>CampaignSubtaskController</code>)</td><td><code>Details</code> thêm <code>subtaskRole</code> (nullable). <code>Row</code> trả thêm <code>subtaskRole</code>. <code>PATCH /{id}/status</code> không cho đặt <code>FINISHED</code> với subtask có vai trò (tự động theo §5.3).</td></tr><tr><td><code>TaskDocument.Subtask</code></td><td>thêm trường <code>subtaskRole</code> (String, nullable).</td></tr><tr><td><code>TaskType</code> enum (BE <code>model/enums/TaskType.java</code>, FE <code>types/task.ts</code>, <code>pages/campaign/types.ts</code>)</td><td>thêm <code>SHORT_VIDEO, KOL_BOOKING, WORKSHOP, EMAIL_NEWSLETTER</code>.</td></tr><tr><td><code>GET/POST /tasks/{taskId}/post</code> (<code>TaskPostController</code>)</td><td>quyền ghi theo phần (AC8) thay cho chỉ <code>TaskApprovalPolicy.assignee</code>. Response thêm <code>sections</code> (trạng thái + quyền người gọi).</td></tr><tr><td><code>POST /tasks/{taskId}/survey</code> (<code>SurveyController</code>)</td><td>quyền ghi theo phần <code>SURVEY.FORM</code>.</td></tr><tr><td><code>POST /tasks/{taskId}/submit</code> (<code>TaskApprovalController</code>)</td><td>thêm điều kiện §5.3.</td></tr><tr><td><code>GET /mail-quota</code> (<code>MailSendController</code>)</td><td>thêm <code>monthlyUsed</code>, <code>monthlyLimit</code>, <code>planName</code>.</td></tr><tr><td><code>POST /mail-recipient-groups</code> (<code>MailRecipientController</code>)</td><td><code>Entry</code> thêm <code>consent</code> (boolean), <code>consentSource</code>, <code>importedAt</code>.</td></tr></tbody></table><h3 id="_9-2-moi" tabindex="-1">9.2 Mới <a class="header-anchor" href="#_9-2-moi" aria-label="Permalink to &quot;9.2 Mới&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method &amp; path</th><th>Mô tả</th><th>Quyền</th></tr></thead><tbody><tr><td><code>GET /api/v1/task-catalog/{taskType}</code></td><td>danh mục vai trò → phần, cờ O/I</td><td>mọi thành viên đã đăng nhập</td></tr><tr><td><code>GET /tasks/{taskId}/sections</code></td><td>mọi phần: key, ownerSubtaskIds, ownerNames, status, revision, returnNote, <code>canEdit</code>, <code>canSubmit</code>, <code>canApprove</code>, <code>canReturn</code>, nội dung. Client chỉ nhận phần O đủ điều kiện.</td><td>thành viên task, Client</td></tr><tr><td><code>PATCH /tasks/{taskId}/sections/{sectionKey}</code></td><td>body <code>{content, expectedRevision}</code>; content là JSON theo schema phần (§3). POST/SURVEY ghi xuống <code>PostDocument</code>/survey hiện có; loại khác ghi vào <code>TaskDocument.typeMetadata.sections</code> hoặc collection riêng — chốt ở plan.md</td><td>§4</td></tr><tr><td><code>POST /tasks/{taskId}/sections/{sectionKey}/submit</code></td><td><code>DRAFT/RETURNED → SUBMITTED</code></td><td>chủ phần, điều phối</td></tr><tr><td><code>POST /tasks/{taskId}/sections/{sectionKey}/approve</code></td><td><code>SUBMITTED → INTERNAL_APPROVED</code> (Manager/supervisor) hoặc <code>INTERNAL_APPROVED → CLIENT_APPROVED</code> (Client)</td><td>§4</td></tr><tr><td><code>POST /tasks/{taskId}/sections/{sectionKey}/return</code></td><td>body <code>{note}</code> bắt buộc; → <code>RETURNED</code></td><td>Manager/supervisor, Client (phần O)</td></tr><tr><td><code>POST /tasks/{taskId}/sections/{sectionKey}/reopen</code></td><td>phần đã duyệt → <code>RETURNED</code></td><td>Manager</td></tr><tr><td><code>POST /mail-recipient-groups/import</code></td><td>multipart CSV (<code>email,name,consent</code>), trả <code>{imported, skippedNoConsent, skippedSuppressed, skippedInvalid}</code></td><td>Manager, Owner</td></tr><tr><td><code>POST /tasks/{taskId}/newsletter/send</code></td><td>body <code>{recipientGroupIds, scheduledAt?}</code>; tạo mail batch qua <code>MailDeliveryService</code>/batch có sẵn; trả batchId</td><td>chủ <code>EMAIL_SEND</code>, điều phối, Manager</td></tr><tr><td><code>POST /tasks/{taskId}/newsletter/send-test</code></td><td>gửi bản test tới email người gọi</td><td>như trên</td></tr></tbody></table><p>Theo dõi batch: dùng lại <code>GET /mail-batches/{batchId}</code>, <code>/export.csv</code>, <code>/cancel</code>, <code>/resend-failed</code>.</p><h2 id="_10-error-handling" tabindex="-1">10. Error Handling <a class="header-anchor" href="#_10-error-handling" aria-label="Permalink to &quot;10. Error Handling&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tình huống</th><th>ErrorCode (có sẵn hoặc mới)</th><th>Thông báo (i18n key)</th></tr></thead><tbody><tr><td>Sửa phần không có quyền / phần đã khoá</td><td><code>FORBIDDEN</code></td><td><code>tasks.sectionActions.forbidden</code> / <code>.locked</code></td></tr><tr><td>Lệch revision</td><td><code>TASK_REVISION_CONFLICT</code> (có sẵn)</td><td><code>tasks.sectionActions.conflict</code> + nút tải lại</td></tr><tr><td><code>subtaskRole</code> sai loại task</td><td><code>VALIDATION_ERROR</code></td><td><code>tasks.subtask.invalidRole</code></td></tr><tr><td>Chuyển trạng thái phần không hợp lệ</td><td><code>SECTION_INVALID_TRANSITION</code> (mới)</td><td><code>tasks.sectionActions.invalidTransition</code></td></tr><tr><td>Trả phần thiếu ghi chú</td><td><code>VALIDATION_ERROR</code></td><td><code>tasks.sectionActions.noteRequired</code></td></tr><tr><td>Nộp task cha khi còn phần chưa duyệt</td><td><code>TASK_SECTIONS_UNAPPROVED</code> (mới)</td><td><code>tasks.sectionActions.sectionsPending</code></td></tr><tr><td>Gửi email khi nội dung chưa duyệt</td><td><code>NEWSLETTER_NOT_APPROVED</code> (mới)</td><td><code>mailTemplate.newsletter.notApproved</code></td></tr><tr><td>Vượt quota tháng</td><td><code>MAIL_MONTHLY_QUOTA_EXCEEDED</code> (mới)</td><td><code>mailTemplate.quota.monthlyExceeded</code></td></tr><tr><td>CSV thiếu cột/sai định dạng</td><td><code>VALIDATION_ERROR</code></td><td><code>mailTemplate.contactImport.invalidFile</code></td></tr></tbody></table><h2 id="_11-edge-cases" tabindex="-1">11. Edge Cases <a class="header-anchor" href="#_11-edge-cases" aria-label="Permalink to &quot;11. Edge Cases&quot;">​</a></h2><ul><li>Subtask bị xoá/huỷ (<code>CANCELLED</code>) khi phần đang <code>SUBMITTED</code>: phần giữ nội dung, mất chủ → về quyền của điều phối/Manager.</li><li>Đổi assignee subtask giữa chừng: giữ nguyên nội dung và trạng thái phần (quyết định 2026-11-09).</li><li>Manager bỏ hết vai trò → task hoạt động như hiện tại (chỉ điều phối sửa).</li><li>Task cũ trước tính năng (không có trạng thái phần): coi mọi phần <code>DRAFT</code>, chủ = điều phối; luồng duyệt task cha giữ nguyên cho task đã ở <code>IN_REVIEW</code> trước khi deploy.</li><li><code>requiresClientApproval = false</code>: phần O kết thúc ở <code>INTERNAL_APPROVED</code>, Client không thấy luồng duyệt.</li><li>Hai người cùng vai trò sửa cùng phần: người lưu sau nhận <code>TASK_REVISION_CONFLICT</code>.</li><li>Client trả phần sau khi task đã lên lịch publish/gửi mail: tự huỷ lịch ngay, thông báo người phụ trách Đăng bài / Gửi; phải duyệt lại rồi đặt lịch lại.</li><li>CSV trùng email: giữ một dòng; email đã unsubscribe ở bất kỳ workspace nào của cùng Client: chặn mọi Newsletter của Client đó (§16.6).</li><li>Hết quota giữa batch: phần đã gửi giữ nguyên, phần còn lại <code>DEFERRED</code> theo cơ chế <code>MailDeliveryService</code> hiện có.</li><li>SHORT_VIDEO khi code của Ân chưa merge: khối Shoot/Edit hiển thị placeholder, phần vẫn duyệt được với media tải lên qua <code>POST.MEDIA</code>-tương đương.</li></ul><h2 id="_12-ui-states" tabindex="-1">12. UI States <a class="header-anchor" href="#_12-ui-states" aria-label="Permalink to &quot;12. UI States&quot;">​</a></h2><p>Mỗi khối phần: loading (skeleton), empty (chưa có nội dung — gợi ý theo vai trò), editing, saving, saved, locked (chỉ đọc + lý do), conflict (banner tải lại), returned (banner ghi chú trả màu cảnh báo), approved (badge xanh), error (toast + giữ nội dung chưa lưu). Danh sách phần cho Client: empty state &quot;Chưa có phần nào chờ duyệt&quot;.</p><h2 id="_13-test-cases-so-bo" tabindex="-1">13. Test Cases (sơ bộ) <a class="header-anchor" href="#_13-test-cases-so-bo" aria-label="Permalink to &quot;13. Test Cases (sơ bộ)&quot;">​</a></h2><ol><li>Tạo task POST → gợi ý 5 vai trò; bỏ <code>POST_RESEARCH</code>, tạo 4 subtask có vai trò + 1 tự do.</li><li>Creator <code>POST_CONTENT</code> lưu caption ✔; lưu media ✖ <code>FORBIDDEN</code>.</li><li>Creator <code>POST_EDITING</code> sửa caption khi DRAFT ✖; sau khi Content nộp ✔.</li><li>Assignee subtask tự do sửa bất kỳ phần ✖.</li><li>Manager duyệt <code>POST.CAPTION</code> → Client thấy phần; Client không thấy <code>POST.BRIEF</code>.</li><li>Client trả <code>POST.MEDIA</code> → chủ phần sửa được lại; <code>POST.CAPTION</code> đã duyệt không đổi.</li><li>Nộp task cha khi còn phần SUBMITTED ✖ <code>TASK_SECTIONS_UNAPPROVED</code>.</li><li>Hai phiên cùng lưu một phần → phiên sau <code>TASK_REVISION_CONFLICT</code>.</li><li>Import CSV 10 dòng, 2 không consent, 1 trong suppression → imported 7.</li><li>Gửi newsletter trước khi Client duyệt ✖; sau duyệt ✔, batch tạo, mail có link unsubscribe.</li><li>Gói BASIC đã gửi 1.000 trong tháng → gửi tiếp ✖ <code>MAIL_MONTHLY_QUOTA_EXCEEDED</code>.</li><li>Mobile: Manager duyệt/trả phần ✔, không có nút sửa nội dung.</li><li>Đổi ngôn ngữ vi↔en trên mọi trình soạn mới không vỡ layout, không lộ key.</li><li>Light/dark: badge trạng thái, khối khoá, banner trả lại đủ tương phản.</li><li>Task cũ (subtask không vai trò) mở trình soạn, sửa, nộp như trước.</li></ol><h2 id="_14-definition-of-done" tabindex="-1">14. Definition of Done <a class="header-anchor" href="#_14-definition-of-done" aria-label="Permalink to &quot;14. Definition of Done&quot;">​</a></h2><ul><li>8 loại task có danh mục, trình soạn chia phần, quyền theo §4 enforce ở backend.</li><li>Duyệt từng phần 2 cấp + gating nộp task cha hoạt động; subtask tự động FINISHED.</li><li>EMAIL_NEWSLETTER gửi thật với consent, suppression, unsubscribe, quota tháng.</li><li>Mobile xem + duyệt/trả phần.</li><li>i18n vi/en key-parallel, light/dark đạt.</li><li>Unit/integration test backend cho quyền &amp; chuyển trạng thái; E2E web cho luồng POST đầy đủ; test.md pass.</li><li>Không regression luồng task cũ.</li></ul><h2 id="_15-out-of-scope" tabindex="-1">15. Out of Scope <a class="header-anchor" href="#_15-out-of-scope" aria-label="Permalink to &quot;15. Out of Scope&quot;">​</a></h2><ul><li>Quay/dựng video và mọi chức năng sửa video trong app (phần của Ân; spec chỉ chừa slot <code>VIDEO.SHOOT</code>, <code>VIDEO.EDIT</code>).</li><li>Thanh toán cho KOL; KOL đăng nhập/nộp bài qua link.</li><li>Gửi mail pitching tới nhà báo.</li><li>Agency tự cấu hình danh mục vai trò/phần.</li><li>Trình soạn đầy đủ trên mobile.</li><li>Đồng soạn real-time nhiều người trên cùng một phần.</li><li>Gửi email từ domain riêng của Client (SPF/DKIM).</li><li>Cập nhật baseline 141 FR, CSV FR và SRS — làm sau khi code chạy thật.</li><li>Lỗi migration <code>media_packages.share_enabled</code>.</li></ul><h2 id="_16-quyet-đinh-đa-chot-user-2026-11-10" tabindex="-1">16. Quyết định đã chốt (user, 2026-11-10) <a class="header-anchor" href="#_16-quyet-đinh-đa-chot-user-2026-11-10" aria-label="Permalink to &quot;16. Quyết định đã chốt (user, 2026-11-10)&quot;">​</a></h2><ol><li><strong>Quota Newsletter tách riêng khỏi mail hệ thống.</strong> Mail hệ thống (thông báo, OTP…) giữ nguyên giới hạn <code>mail.quota.*</code> hiện có (100/ngày/workspace, 450/ngày toàn hệ thống) để Newsletter không chiếm hết. Newsletter có bộ đếm riêng: quota tháng theo gói (BASIC 1.000 / PRO 10.000 / ENTERPRISE 50.000) + giới hạn tốc độ gửi theo ngày cấu hình được.</li><li><strong>Quota tính theo agency.</strong> Mọi workspace/Client của một agency dùng chung quota tháng.</li><li><strong>Không làm tracking open/click.</strong> Báo cáo email gồm: đã gửi, thành công, lỗi/bounce, huỷ đăng ký, cùng ô nhận xét.</li><li><strong>Thêm <code>PackageServiceType</code>:</strong> <code>SHORT_VIDEO</code>, <code>KOL_BOOKING</code>, <code>EMAIL_NEWSLETTER</code> (Workshop đã có <code>WORKSHOP_SUPPORT</code>).</li><li><strong>Client duyệt từng phần thay hẳn bước <code>reviewStep = CLIENT</code></strong> với task có subtask theo vai trò. Client duyệt đủ các phần đầu ra thì task được coi là đã duyệt. Task cũ (không có subtask theo vai trò) giữ luồng duyệt cũ.</li><li><strong>Huỷ đăng ký theo Client.</strong> Người nhận huỷ đăng ký Newsletter ở một workspace thì bị chặn mọi Newsletter của Client đó, ở mọi workspace. Suppression hiện có (theo workspace + agency) giữ cho mail hệ thống; Newsletter thêm phạm vi Client.</li><li><strong>Thông báo:</strong> in-app cho mọi sự kiện nộp/duyệt/trả/mở lại phần. Email cho Client khi có phần chờ Client duyệt, và cho chủ phần khi phần bị trả. Phần chờ Client quá 48h thì nhắc lại bằng email; <strong>không tự duyệt</strong>.</li><li><strong>Hạn subtask:</strong> subtask sinh theo danh mục mặc định lấy hạn của task cha; Manager sửa được từng subtask.</li><li><strong>Sinh subtask khi triển khai chiến dịch.</strong> Code hiện tại đã tự sinh task cha từ hạng mục gói lúc triển khai chiến dịch (<code>CampaignTaskStore.draftTask</code>) nhưng chưa sinh subtask. Bổ sung: mỗi task cha sinh ra kèm đủ bộ subtask theo danh mục của loại đó, chưa gán người, hạn = hạn task cha. Manager gán người, sửa hạn, huỷ subtask không cần. Task tạo tay ngoài gói vẫn dùng bước &quot;Gợi ý theo danh mục&quot; như §8.</li><li><strong>Ai xem phần nội bộ:</strong> chỉ người tham gia task (điều phối, người có subtask trong task, supervisor), Manager và Owner. Creator khác trong workspace không thấy phần nội bộ. Ghi đè cột &quot;Xem phần internal&quot; ở §4 cho người không tham gia task.</li><li><strong>Xuất file:</strong> thông cáo báo chí xuất DOCX; các loại khác xuất PDF. File chỉ gồm phần đầu ra (O), có logo thương hiệu Client; phần nội bộ không bao giờ vào file. Agency (người tham gia task, Manager) xuất ở mọi trạng thái, phần chưa Client duyệt đóng dấu &quot;Bản nháp&quot;. Client chỉ xuất được phần đã <code>CLIENT_APPROVED</code>. Dùng lại hạ tầng xuất đề xuất đa ngôn ngữ hiện có nếu phù hợp.</li><li><strong>Phiên bản:</strong> mỗi lần nộp phần lưu một bản chụp nội dung; xem và so sánh được giữa các bản. Không xoá phiên bản. Kèm nhật ký sự kiện (ai nộp/duyệt/trả/mở lại, ghi chú, thời điểm).</li><li><strong>Khôi phục bản cũ:</strong> chủ phần (khi phần đang <code>DRAFT</code>/<code>RETURNED</code>), người điều phối, Manager. Khôi phục = chép nội dung bản cũ vào bản nháp hiện tại; phần phải nộp và duyệt lại.</li><li><strong>Client không xem lịch sử phiên bản</strong>, chỉ thấy bản hiện tại đang chờ duyệt hoặc đã duyệt.</li><li><strong>Theo dõi tiến độ:</strong> không làm màn hình workload riêng. Timeline chiến dịch có sẵn hiện subtask kèm trạng thái phần và cờ trễ hạn / chờ Client.</li></ol>',82)])])}const p=n(i,[["render",h]]);export{u as __pageData,p as default};
